# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
TOTAL_STAGES=20
QA_FIRST=1
QA_LAST=20
QA_MODE=all
stage_name() {
  case "$1" in
    1) printf '%s\n' 'Target and four browser profiles' ;;
    2) printf '%s\n' 'Register, login and invalid input' ;;
    3) printf '%s\n' 'Profile, photos and social controls' ;;
    4) printf '%s\n' 'Private 1v1 Lobby admission' ;;
    5) printf '%s\n' 'Editor, languages and draft controls' ;;
    6) printf '%s\n' 'Visible Run and error results' ;;
    7) printf '%s\n' 'Submit, sealed results and score reveal' ;;
    8) printf '%s\n' 'Full Match, deadline and deliberate leave' ;;
    9) printf '%s\n' 'Four-player 2v2 Lobby' ;;
    10) printf '%s\n' 'Shared editing, language and revision readiness' ;;
    11) printf '%s\n' 'Chat, quick pings and isolation' ;;
    12) printf '%s\n' 'Offline reconnect and hard reload' ;;
    13) printf '%s\n' 'Natural 15-minute session expiry' ;;
    14) printf '%s\n' 'Logout and account replacement' ;;
    15) printf '%s\n' 'Failed logout and no automatic replay' ;;
    16) printf '%s\n' 'Auth outage, Game restart and recovery' ;;
    17) printf '%s\n' 'Layout, keyboard and accessibility' ;;
    18) printf '%s\n' 'Separate-computer play' ;;
    19) printf '%s\n' 'Live OAuth and email (optional)' ;;
    20) printf '%s\n' 'Review results and remaining coverage' ;;
  esac
}
usage() {
  printf '%s\n' 'Usage: bash scripts/manual-game-test.sh [--list | --group 1..5 | --from 1..20 | --help]'
  printf '%s\n' 'Groups: 1 access; 2 solo game; 3 team game; 4 session/recovery; 5 final checks.'
  printf '%s\n' 'This wizard opens the test URL and records human observations. It does not run services, tests or fault commands.'
}
while [[ $# -gt 0 ]]; do
  case "$1" in
    --help|-h) usage; return 0 ;;
    --list) for QA_N in {1..20}; do printf '%2s  %s\n' "$QA_N" "$(stage_name "$QA_N")"; done; return 0 ;;
    --group)
      [[ $# -ge 2 && "$2" =~ ^[1-5]$ && "$QA_MODE" == all ]] || { usage >&2; return 2; }
      QA_FIRST=$((($2 - 1) * 4 + 1)); QA_LAST=$(($2 * 4)); QA_MODE=group; shift 2 ;;
    --from)
      [[ $# -ge 2 && "$2" =~ ^([1-9]|1[0-9]|20)$ && "$QA_MODE" == all ]] || { usage >&2; return 2; }
      QA_FIRST="$2"; QA_MODE=from; shift 2 ;;
    *) usage >&2; return 2 ;;
  esac
done
if [[ ! -t 0 || ! -t 1 ]]; then
  printf '%s\n' 'Run interactively in a terminal. Use --list or --help for noninteractive inspection.' >&2
  return 2
fi
QA_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$QA_ROOT/.scratch/manual-game-testing/settings.env"
umask 077
mkdir -p "$QA_ROOT/.scratch/manual-game-testing/runs"
QA_REPORT="$QA_ROOT/.scratch/manual-game-testing/runs/$(date -u +%Y%m%dT%H%M%SZ)-$$.md"
trap 'if [[ -f "$QA_REPORT" ]]; then printf "\nLocal report: %s\n" "$QA_REPORT"; fi' EXIT
banner 'Code Arena manual testing'
say 'Select a disposable test origin. Recommended full-stack origin: https://localhost'
say 'Services must already be started using guide section 2. This wizard never changes application .env.'
while :; do
  ask QA_BASE_URL 'Test origin (Enter = https://localhost):' || return 1
  QA_BASE_URL="${QA_BASE_URL:-https://localhost}"
  QA_BASE_URL="${QA_BASE_URL%/}"
  [[ "$QA_BASE_URL" =~ ^https?://[A-Za-z0-9][A-Za-z0-9.-]*(:[0-9]+)?$ ]] && break
  warn 'Use an http(s) origin with optional port only; no path, query, user or password.'
done
write_env QA_BASE_URL "$QA_BASE_URL"
{
  printf '# Manual game test observations\n\n'
  printf 'Origin: %s\n\n' "$QA_BASE_URL"
  printf 'Commit: %s\n\n' "$(git -C "$QA_ROOT" rev-parse --short HEAD 2>/dev/null || printf unknown)"
  printf 'Selected stages: %s to %s. All other stages are UNTESTED.\n\n' "$QA_FIRST" "$QA_LAST"
  printf '| Stage | Result | Notes |\n| --- | --- | --- |\n'
} > "$QA_REPORT"
select_stage() {
  [[ "$1" -ge "$QA_FIRST" && "$1" -le "$QA_LAST" ]] || return 1
  _STAGE_INDEX=$(($1 - 1))
}
record_result() {
  local QA_STAGE="$1" QA_RESULT='' QA_NOTE=''
  while :; do
    ask QA_RESULT 'Observed result: PASS, FAIL or SKIP:' || return 1
    case "$QA_RESULT" in
      PASS|pass) QA_RESULT=PASS; break ;;
      FAIL|fail) QA_RESULT=FAIL; break ;;
      SKIP|skip) QA_RESULT=SKIP; break ;;
      *) warn 'Enter PASS, FAIL or SKIP explicitly. Empty input is not a pass.' ;;
    esac
  done
  ask QA_NOTE 'Short note (no credentials; Enter = none):' || return 1
  QA_NOTE="${QA_NOTE//|/\\|}"
  printf '| %s. %s | %s | %s |\n' "$QA_STAGE" "$(stage_name "$QA_STAGE")" "$QA_RESULT" "$QA_NOTE" >> "$QA_REPORT"
}

if select_stage 1; then
