  stage 'Review results and remaining coverage'
  note 'Estimate: 5 min. Guide: docs/manual-game-testing.md, stage 20.'
  step 'Read the result report path printed below. Check every observed failure includes steps, expected result and actual result.'
  step 'Mark untested prerequisites as SKIP, not PASS. A partial --group run leaves other stages untested.'
  step 'Use the command reference for API queue, security, concurrency, database, ownership and exact scoring races.'
  step 'Keep reports local; share only reviewed nonsecret evidence.'
  say 'Expected: The report distinguishes PASS, FAIL, SKIP and untested stages. Completing this wizard alone does not prove every automated or deployment requirement.'
  say "Report: $QA_REPORT"
  record_result 20
fi

finish
printf '%s\n' 'Wizard finished. This is not an automatic game PASS.'
printf 'Local report: %s\n' "$QA_REPORT"
awk -F '|' '$3 ~ /PASS/ {p++} $3 ~ /FAIL/ {f++} $3 ~ /SKIP/ {s++} END {printf "Observed: %d PASS, %d FAIL, %d SKIP, %d UNTESTED.\n", p, f, s, 20-p-f-s}' "$QA_REPORT"
}

run_wizard "$@"; exit
